21	static uint8_t* ReadFile(const char* path, size_t* out_size) {
22	  FILE* f = fopen(path, "rb");
23	  if (!f) {
24	    printf("Cannot open %s\n", path);
25	    return nullptr;
26	  }
27	  fseek(f, 0, SEEK_END);
28	  long sz = ftell(f);
29	  fseek(f, 0, SEEK_SET);
30	  uint8_t* buf = static_cast<uint8_t*>(malloc(sz));
31	  if (!buf) {
32	    printf("malloc(%ld) failed for %s\n", sz, path);
33	    fclose(f);
34	    return nullptr;
35	  }
36	  size_t rd = fread(buf, 1, sz, f);
37	  fclose(f);
38	  if (rd != static_cast<size_t>(sz)) {
39	    printf("Read %zu/%ld bytes from %s\n", rd, sz, path);
40	    free(buf);
41	    return nullptr;
42	  }
43	  *out_size = static_cast<size_t>(sz);
44	  return buf;
45	}
