37	bool PrepareF32ScratchBuffer(TfLiteContext* context, int32_t scratch_size,
38	                             F32KernelState* state) {
39	  InitializeF32KernelState(state);
40	  if (state == nullptr || scratch_size < 0) {
41	    return false;
42	  }
43	
44	  if (scratch_size == 0) {
45	    state->enabled = true;
46	    return true;
47	  }
48	
49	  if (context == nullptr || context->RequestScratchBufferInArena == nullptr) {
50	    return false;
51	  }
52	
53	  int scratch_buffer_index = -1;
54	  if (context->RequestScratchBufferInArena(
55	          context, scratch_size, &scratch_buffer_index) != kTfLiteOk ||
56	      scratch_buffer_index < 0) {
57	    return false;
58	  }
59	
60	  state->enabled = true;
61	  state->scratch_buffer_index = scratch_buffer_index;
62	  state->scratch_buffer_size = scratch_size;
63	  return true;
64	}
