66	bool GetF32ScratchBuffer(TfLiteContext* context, const F32KernelState& state,
67	                         void** buffer) {
68	  if (buffer == nullptr || !state.enabled) {
69	    return false;
70	  }
71	
72	  *buffer = nullptr;
73	  if (state.scratch_buffer_size == 0) {
74	    return true;
75	  }
76	
77	  if (context == nullptr || context->GetScratchBuffer == nullptr ||
78	      state.scratch_buffer_index < 0) {
79	    return false;
80	  }
81	
82	  *buffer = context->GetScratchBuffer(context, state.scratch_buffer_index);
83	  return *buffer != nullptr;
84	}
