54	TfLiteStatus PrepareConvF32(
55	    TfLiteContext* context, const TfLiteConvParams& params,
56	    const TfLiteTensor* input, const TfLiteTensor* filter,
57	    const TfLiteTensor* bias, const TfLiteTensor* output,
58	    const OpDataConv& reference_op_data, ConvF32State* state) {
59	  if (state == nullptr) {
60	    return kTfLiteError;
61	  }
62	  InitializeF32KernelState(&state->kernel);
63	
64	  if (!HasPositiveDims(input) || !HasPositiveDims(filter) ||
65	      !HasPositiveDims(output) || input->type != kTfLiteFloat32 ||
66	      filter->type != kTfLiteFloat32 || output->type != kTfLiteFloat32 ||
67	      (bias != nullptr &&
68	       (bias->type != kTfLiteFloat32 || bias->dims == nullptr ||
69	        (bias->dims->size != 1 && bias->dims->size != 4))) ||
70	      params.stride_height <= 0 || params.stride_width <= 0 ||
71	      params.dilation_height_factor <= 0 || params.dilation_width_factor <= 0) {
72	    return kTfLiteOk;
73	  }
74	
75	  const int input_channels = input->dims->data[3];
76	  const int filter_input_channels = filter->dims->data[3];
77	  const int output_channels = output->dims->data[3];
78	  if (input->dims->data[0] != output->dims->data[0] ||
79	      input_channels != filter_input_channels ||
80	      filter->dims->data[0] != output_channels ||
81	      (bias != nullptr && NumElements(bias) != output_channels)) {
82	    return kTfLiteOk;
83	  }
84	
85	  state->params = {};
86	  state->params.stride.h = params.stride_height;
87	  state->params.stride.w = params.stride_width;
88	  state->params.padding.h = reference_op_data.padding.height;
89	  state->params.padding.w = reference_op_data.padding.width;
90	  state->params.dilation.h = params.dilation_height_factor;
91	  state->params.dilation.w = params.dilation_width_factor;
