107	
108	F32DispatchResult EvalConvF32(TfLiteContext* context,
109	                              const TfLiteEvalTensor* input,
110	                              const TfLiteEvalTensor* filter,
111	                              const TfLiteEvalTensor* bias,
112	                              TfLiteEvalTensor* output,
113	                              const ConvF32State& state) {
114	  if (!state.kernel.enabled) {
115	    RecordF32Dispatch(F32DispatchResult::kFallback, 0);
116	    return F32DispatchResult::kFallback;
117	  }
118	
119	  void* scratch = nullptr;
120	  if (!GetF32ScratchBuffer(context, state.kernel, &scratch)) {
121	    RecordF32Dispatch(F32DispatchResult::kFallback, 0);
122	    return F32DispatchResult::kFallback;
123	  }
124	
125	  cmsis_nn_context cmsis_context = {};
126	  cmsis_context.buf = scratch;
127	  cmsis_context.size = state.kernel.scratch_buffer_size;
128	
129	#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
130	  const uint32_t start_ticks = GetCurrentTimeTicks();
131	#endif
132	  const arm_cmsis_nn_status status = arm_convolve_wrapper_f32(
133	      &cmsis_context, &state.params, &state.input_dims,
134	      tflite::micro::GetTensorData<float>(input), &state.filter_dims,
135	      tflite::micro::GetTensorData<float>(filter), &state.bias_dims,
136	      tflite::micro::GetOptionalTensorData<float>(bias), &state.output_dims,
137	      tflite::micro::GetTensorData<float>(output));
138	#if defined(TFLITE_MICRO_CMSIS_NN_F32_PROFILE)
139	  const uint32_t elapsed_ticks = GetCurrentTimeTicks() - start_ticks;
140	#else
141	  const uint32_t elapsed_ticks = 0;
142	#endif
143	
144	  const F32DispatchResult result = status == ARM_CMSIS_NN_SUCCESS
145	                                       ? F32DispatchResult::kHandled
146	                                       : F32DispatchResult::kCmsisError;
147	  RecordF32Dispatch(result, elapsed_ticks);
148	  return result;
149	}
