355	uint32_t ComputeCRC32(const uint8_t* data, const size_t data_length) {
356	  uint32_t crc32 = ~0U;
357	
358	  for (size_t i = 0; i < data_length; i++) {
359	    // crctab is an array of 256 32-bit constants
360	    const uint32_t index = (crc32 ^ data[i]) & (kCrctabLen - 1);
361	    crc32 = (crc32 >> 8) ^ crctab[index];
362	  }
363	
364	  // invert all bits of result
365	  crc32 ^= ~0U;
366	  return crc32;
367	}
