49	bool RunDirectConv1Comparison(const char* input_file, const char* filter_file,
50	                              const char* bias_file, float* max_abs_error) {
51	  constexpr size_t kInputCount = 32;
52	  constexpr size_t kInputElements = 1 * 1 * 276 * 1;
53	  constexpr size_t kFilterElements = 32 * 1 * 21 * 1;
54	  constexpr size_t kBiasElements = 32;
55	  constexpr size_t kOutputElements = 1 * 1 * 128 * 32;
56	  constexpr size_t kInputBytes =
57	      kInputCount * kInputElements * sizeof(float);
58	  constexpr size_t kFilterBytes = kFilterElements * sizeof(float);
59	  constexpr size_t kBiasBytes = kBiasElements * sizeof(float);
60	  constexpr size_t kOutputBytes = kOutputElements * sizeof(float);
61	  constexpr float kDirectTolerance = 1e-5f;
62	
63	  size_t input_size = 0;
64	  size_t filter_size = 0;
65	  size_t bias_size = 0;
66	  uint8_t* input_buf =
67	      tflm_test_util::LoadDataFile(input_file, &input_size);
68	  uint8_t* filter_buf = nullptr;
69	  uint8_t* bias_buf = nullptr;
70	  float* reference_output = nullptr;
71	  float* cmsis_output = nullptr;
72	  void* scratch = nullptr;
73	
74	  auto cleanup = [&]() {
75	    free(scratch);
76	    free(cmsis_output);
77	    free(reference_output);
78	    free(bias_buf);
79	    free(filter_buf);
80	    free(input_buf);
81	  };
82	
83	  if (input_buf == nullptr) {
84	    cleanup();
85	    return false;
86	  }
87	  filter_buf = tflm_test_util::LoadDataFile(filter_file, &filter_size);
88	  if (filter_buf == nullptr) {
89	    cleanup();
90	    return false;
91	  }
92	  bias_buf = tflm_test_util::LoadDataFile(bias_file, &bias_size);
93	  if (bias_buf == nullptr) {
94	    cleanup();
95	    return false;
96	  }
97	
98	  if (input_size != kInputBytes || filter_size != kFilterBytes ||
99	      bias_size != kBiasBytes) {
100	    printf("ERROR: direct Conv1 fixture sizes input=%zu/%zu filter=%zu/%zu "
101	           "bias=%zu/%zu\n",
102	           input_size, kInputBytes, filter_size, kFilterBytes, bias_size,
103	           kBiasBytes);
104	    cleanup();
105	    return false;
106	  }
107	
108	  reference_output = static_cast<float*>(malloc(kOutputBytes));
109	  cmsis_output = static_cast<float*>(malloc(kOutputBytes));
110	  if (reference_output == nullptr || cmsis_output == nullptr) {
111	    printf("ERROR: direct Conv1 output allocation failed\n");
112	    cleanup();
113	    return false;
114	  }
115	
116	  tflite::ConvParams reference_params = {};
117	  reference_params.stride_height = 1;
118	  reference_params.stride_width = 2;
119	  reference_params.dilation_height_factor = 1;
120	  reference_params.dilation_width_factor = 1;
121	  reference_params.padding_type = tflite::PaddingType::kValid;
122	  reference_params.padding_values.height = 0;
123	  reference_params.padding_values.width = 0;
124	  reference_params.float_activation_min = 0.0f;
125	  reference_params.float_activation_max = FLT_MAX;
126	
127	  const int32_t reference_input_dims[] = {1, 1, 276, 1};
128	  const int32_t reference_filter_dims[] = {32, 1, 21, 1};
129	  const int32_t reference_bias_dims[] = {32};
130	  const int32_t reference_output_dims[] = {1, 1, 128, 32};
131	  const tflite::RuntimeShape reference_input_shape(4, reference_input_dims);
132	  const tflite::RuntimeShape reference_filter_shape(4, reference_filter_dims);
133	  const tflite::RuntimeShape reference_bias_shape(1, reference_bias_dims);
134	  const tflite::RuntimeShape reference_output_shape(4, reference_output_dims);
135	
136	  cmsis_nn_conv_params_f32 cmsis_params = {};
137	  cmsis_params.stride.h = 1;
138	  cmsis_params.stride.w = 2;
139	  cmsis_params.padding.h = 0;
140	  cmsis_params.padding.w = 0;
141	  cmsis_params.dilation.h = 1;
142	  cmsis_params.dilation.w = 1;
143	  cmsis_params.activation.min = 0.0f;
144	  cmsis_params.activation.max = FLT_MAX;
145	  cmsis_params.weight_format = ARM_NN_WEIGHT_FORMAT_STANDARD;
146	  const cmsis_nn_dims cmsis_input_dims = {1, 1, 276, 1};
147	  const cmsis_nn_dims cmsis_filter_dims = {32, 1, 21, 1};
148	  const cmsis_nn_dims cmsis_bias_dims = {1, 1, 1, 32};
149	  const cmsis_nn_dims cmsis_output_dims = {1, 1, 128, 32};
150	
151	  const int32_t scratch_size = arm_convolve_f32_get_buffer_size(
152	      &cmsis_params, &cmsis_input_dims, &cmsis_filter_dims,
153	      &cmsis_output_dims, ARM_NN_LAYOUT_NHWC);
154	  if (scratch_size < 0) {
155	    printf("ERROR: direct Conv1 invalid scratch size %ld\n",
156	           static_cast<long>(scratch_size));
157	    cleanup();
158	    return false;
159	  }
160	  if (scratch_size > 0) {
161	    scratch = malloc(static_cast<size_t>(scratch_size));
162	    if (scratch == nullptr) {
163	      printf("ERROR: direct Conv1 scratch allocation failed (%ld bytes)\n",
164	             static_cast<long>(scratch_size));
165	      cleanup();
166	      return false;
167	    }
168	  }
169	  cmsis_nn_context cmsis_context = {};
170	  cmsis_context.buf = scratch;
171	  cmsis_context.size = scratch_size;
172	
173	  const float* inputs = reinterpret_cast<const float*>(input_buf);
174	  const float* filter = reinterpret_cast<const float*>(filter_buf);
175	  const float* bias = reinterpret_cast<const float*>(bias_buf);
176	  float direct_max_abs_error = 0.0f;
177	  for (size_t sample = 0; sample < kInputCount; ++sample) {
178	    const float* sample_input = inputs + sample * kInputElements;
179	    tflite::reference_ops::Conv(
180	        reference_params, reference_input_shape, sample_input,
181	        reference_filter_shape, filter, reference_bias_shape, bias,
182	        reference_output_shape, reference_output, tflite::RuntimeShape(),
183	        nullptr);
184	    const arm_cmsis_nn_status status = arm_convolve_f32(
185	        &cmsis_context, &cmsis_params, &cmsis_input_dims, sample_input,
186	        &cmsis_filter_dims, filter, &cmsis_bias_dims, bias,
187	        &cmsis_output_dims, cmsis_output, ARM_NN_LAYOUT_NHWC);
188	    if (status != ARM_CMSIS_NN_SUCCESS) {
189	      printf("ERROR: direct Conv1 CMSIS failure at sample %zu status=%d\n",
190	             sample, static_cast<int>(status));
191	      cleanup();
192	      return false;
193	    }
194	
195	    for (size_t element = 0; element < kOutputElements; ++element) {
196	      const float reference_value = reference_output[element];
197	      const float cmsis_value = cmsis_output[element];
198	      const float difference = std::fabs(reference_value - cmsis_value);
199	      if (!std::isfinite(reference_value) || !std::isfinite(cmsis_value) ||
200	          !std::isfinite(difference)) {
201	        printf("ERROR: direct Conv1 non-finite sample=%zu element=%zu\n",
202	               sample, element);
203	        cleanup();
204	        return false;
205	      }
206	      if (difference > direct_max_abs_error) {
207	        direct_max_abs_error = difference;
208	      }
209	    }
210	  }
211	
212	  *max_abs_error = direct_max_abs_error;
213	  if (direct_max_abs_error > kDirectTolerance) {
214	    printf("ERROR: direct Conv1 max_abs_error %.9g > %.9g\n",
215	           static_cast<double>(direct_max_abs_error),
216	           static_cast<double>(kDirectTolerance));
217	    cleanup();
218	    return false;
219	  }
220	
221	  cleanup();
222	  return true;
223	}
