254	/* Locate the raw data payload inside a NumPy .npy buffer by skipping the
255	 * header.  If the buffer is not a .npy file, the whole buffer is returned
256	 * (backward compatible with raw .bin inputs).
257	 * numpy format (all multi-byte ints are little-endian):
258	 *   magic(6) \x93NUMPY + version(2: major, minor)
259	 *   v1.x: header_len(2 LE) + header + data   (header_offset = 10)
260	 *   v2.x: header_len(4 LE) + header + data   (header_offset = 12)
261	 *   v3.x: header_len(4 LE) + header + data   (header_offset = 12)
262	 * Returns true when a .npy header was recognized and stripped.
263	 */
264	bool NpyPayload(const uint8_t* buf, size_t buf_size,
265	                const uint8_t** out_payload, size_t* out_payload_size) {
266	  static const uint8_t kMagic[6] = {0x93, 'N', 'U', 'M', 'P', 'Y'};
267	  /* 6 (magic) + 2 (version) + 2 (v1 header_len) = 10 minimum */
268	  if (buf_size < 10 || memcmp(buf, kMagic, 6) != 0) {
269	    *out_payload = buf;
270	    *out_payload_size = buf_size;
271	    return false;  /* not npy, treat as raw binary */
272	  }
273	  const uint8_t ver_major = buf[6];
274	  size_t header_len;
275	  size_t header_offset;
276	  if (ver_major == 1) {
277	    /* version(2) at buf[6..7], header_len(2 LE) at buf[8..9] */
278	    header_len = static_cast<size_t>(buf[8]) |
279	                 (static_cast<size_t>(buf[9]) << 8);
280	    header_offset = 10;
281	  } else if (ver_major == 2 || ver_major == 3) {
282	    /* version(2) at buf[6..7], header_len(4 LE) at buf[8..11] */
283	    if (buf_size < 12) {
284	      *out_payload = buf;
285	      *out_payload_size = buf_size;
286	      return false;
287	    }
288	    header_len = static_cast<size_t>(buf[8]) |
289	                 (static_cast<size_t>(buf[9]) << 8) |
290	                 (static_cast<size_t>(buf[10]) << 16) |
291	                 (static_cast<size_t>(buf[11]) << 24);
292	    header_offset = 12;
293	  } else {
294	    *out_payload = buf;
295	    *out_payload_size = buf_size;
296	    return false;
297	  }
298	  const size_t data_offset = header_offset + header_len;
299	  if (data_offset > buf_size) {
300	    *out_payload = buf;
301	    *out_payload_size = buf_size;
302	    return false;
303	  }
304	  *out_payload = buf + data_offset;
305	  *out_payload_size = buf_size - data_offset;
306	  return true;
307	}
