47	static int RunTest(const char* label, const char* model_path,
48	                   const char* input_path, const char* ref_path,
49	                   float tolerance) {
50	  printf("\n=== %s ===\n", label);
51	
52	  size_t model_size = 0;
53	  uint8_t* model_buf = ReadFile(model_path, &model_size);
54	  if (!model_buf) return 1;
55	  printf("Model: %zu bytes\n", model_size);
56	
57	  const tflite::Model* model = tflite::GetModel(model_buf);
58	  if (!model) {
59	    printf("GetModel FAILED\n");
60	    free(model_buf);
61	    return 1;
62	  }
63	
64	  size_t input_size = 0;
65	  uint8_t* input_buf = ReadFile(input_path, &input_size);
66	  if (!input_buf) { free(model_buf); return 1; }
67	
68	  size_t ref_size = 0;
69	  uint8_t* ref_buf = ReadFile(ref_path, &ref_size);
70	  if (!ref_buf) { free(input_buf); free(model_buf); return 1; }
71	
72	  tflite::MicroMutableOpResolver<5> resolver;
73	  resolver.AddFullyConnected();
74	  resolver.AddElu();
75	  resolver.AddSoftmax();
76	  TFLMRegistration bigru_reg = tflite::Register_BIDIRECTIONAL_SEQUENCE_GRU();
77	  resolver.AddCustom("BIDIRECTIONAL_SEQUENCE_GRU", &bigru_reg);
78	  TFLMRegistration ln_reg = tflite::Register_LAYER_NORM();
79	  resolver.AddCustom("LAYER_NORM", &ln_reg);
80	
81	  uint8_t* arena_raw = static_cast<uint8_t*>(malloc(kArenaSize + 15));
82	  if (!arena_raw) {
83	    printf("malloc arena (%zu) FAILED\n", kArenaSize);
84	    free(ref_buf); free(input_buf); free(model_buf);
85	    return 1;
86	  }
87	  uint8_t* tensor_arena = reinterpret_cast<uint8_t*>(
88	      (reinterpret_cast<uintptr_t>(arena_raw) + 15) & ~static_cast<uintptr_t>(15));
89	
90	  tflite::RecordingMicroAllocator* allocator(
91	      tflite::RecordingMicroAllocator::Create(tensor_arena, kArenaSize));
92	  tflite::MicroInterpreter interp(model, resolver, allocator);
93	  if (interp.AllocateTensors() != kTfLiteOk) {
94	    printf("AllocateTensors FAILED\n");
95	    free(arena_raw); free(ref_buf); free(input_buf); free(model_buf);
96	    return 1;
97	  }
98	  printf("Arena: %d/%d bytes\n", (int)interp.arena_used_bytes(),
99	         (int)kArenaSize);
100	
101	  TfLiteTensor* input = interp.input_tensor(0);
102	  if (!input || input->bytes != input_size) {
103	    printf("Input mismatch: got=%d expected=%zu\n",
104	           input ? (int)input->bytes : -1, input_size);
105	    free(arena_raw); free(ref_buf); free(input_buf); free(model_buf);
106	    return 1;
107	  }
108	  memcpy(input->data.raw, input_buf, input->bytes);
109	
110	  // Input CRC32
111	  {
112	    static uint32_t crc_table[256];
113	    static bool crc_init = false;
114	    if (!crc_init) {
115	      for (uint32_t i = 0; i < 256; ++i) {
116	        uint32_t c = i;
117	        for (int k = 0; k < 8; ++k)
118	          c = (c & 1) ? (0xEDB88320U ^ (c >> 1)) : (c >> 1);
119	        crc_table[i] = c;
120	      }
121	      crc_init = true;
122	    }
123	    uint32_t crc = ~0U;
124	    const uint8_t* p = reinterpret_cast<const uint8_t*>(input->data.raw);
125	    for (size_t i = 0; i < input->bytes; ++i) {
126	      crc = (crc >> 8) ^ crc_table[(crc ^ p[i]) & 0xFF];
127	    }
128	    crc ^= ~0U;
129	    printf("Input CRC32: 0x%X\n", (unsigned int)crc);
130	  }
131	
132	  if (interp.Invoke() != kTfLiteOk) {
133	    printf("Invoke FAILED\n");
134	    free(ref_buf); free(input_buf); free(model_buf);
135	    return 1;
136	  }
137	
138	  const TfLiteTensor* output = interp.output_tensor(0);
139	  const float* got = reinterpret_cast<const float*>(output->data.raw);
140	  const float* ref = reinterpret_cast<const float*>(ref_buf);
141	  const int n = output->bytes / sizeof(float);
142	
143	  float max_diff = 0, sum_diff = 0;
144	  for (int i = 0; i < n; ++i) {
145	    float d = std::fabs(got[i] - ref[i]);
146	    if (d > max_diff) max_diff = d;
147	    sum_diff += d;
148	  }
149	
150	  printf("max_diff=%.6e mean_diff=%.6e\n", static_cast<double>(max_diff),
151	         static_cast<double>(sum_diff / n));
152	  printf("out[0:4]: %.6f %.6f %.6f %.6f\n", static_cast<double>(got[0]),
153	         static_cast<double>(got[1]), static_cast<double>(got[2]),
154	         static_cast<double>(got[3]));
155	  printf("ref[0:4]: %.6f %.6f %.6f %.6f\n", static_cast<double>(ref[0]),
156	         static_cast<double>(ref[1]), static_cast<double>(ref[2]),
157	         static_cast<double>(ref[3]));
158	
159	  // Output CRC32
160	  {
161	    static uint32_t crc_table[256];
162	    static bool crc_init = false;
163	    if (!crc_init) {
164	      for (uint32_t i = 0; i < 256; ++i) {
165	        uint32_t c = i;
166	        for (int k = 0; k < 8; ++k)
167	          c = (c & 1) ? (0xEDB88320U ^ (c >> 1)) : (c >> 1);
168	        crc_table[i] = c;
169	      }
170	      crc_init = true;
171	    }
172	    uint32_t crc = ~0U;
173	    const uint8_t* p = reinterpret_cast<const uint8_t*>(output->data.raw);
174	    for (size_t i = 0; i < output->bytes; ++i) {
175	      crc = (crc >> 8) ^ crc_table[(crc ^ p[i]) & 0xFF];
176	    }
177	    crc ^= ~0U;
178	    printf("Output CRC32: 0x%X\n", (unsigned int)crc);
179	  }
180	  free(ref_buf);
181	
182	  constexpr int kRuns = 5;
183	  struct timespec t0, t1;
184	  clock_gettime(CLOCK_MONOTONIC, &t0);
185	  for (int i = 0; i < kRuns; ++i) {
186	    memcpy(input->data.raw, input_buf, input->bytes);
187	    interp.Invoke();
188	  }
189	  clock_gettime(CLOCK_MONOTONIC, &t1);
190	  long total_ms = (t1.tv_sec - t0.tv_sec) * 1000 +
191	                  (t1.tv_nsec - t0.tv_nsec) / 1000000;
192	  printf("[%s] %d runs  total=%ld ms  avg=%.1f ms\n",
193	         label, kRuns, total_ms, (float)total_ms / kRuns);
194	
195	  // Arena allocation breakdown (NonPersistent / Persistent)
196	  tflite::LogAllocatorEvents(*allocator, tflite::PrettyPrintType::kCsv);
197	
198	  free(input_buf);
199	  free(arena_raw);
200	  free(model_buf);
201	
202	  int pass = (max_diff < tolerance) ? 1 : 0;
203	  printf("[%s] %s (max_diff=%.6e, tolerance=%.6e)\n",
204	         label, pass ? "PASS" : "FAIL",
205	         static_cast<double>(max_diff), static_cast<double>(tolerance));
206	  return pass ? 0 : 1;
207	}
