509	/* Generic, shape-agnostic input loader for mlzoo_test: copies raw bytes into
510	 * each input tensor in turn (1..N inputs supported).  Does not enforce a
511	 * fixed shape so it works for any model whose input bytes match the file
512	 * payload size.
513	 */
514	bool SetGenericInput(tflite::MicroInterpreter& interpreter,
515	                     const uint8_t* input_data, size_t input_size) {
516	  size_t offset = 0;
517	  for (size_t i = 0; i < interpreter.inputs_size(); ++i) {
518	    TfLiteTensor* input = interpreter.input_tensor(i);
519	    if (input == nullptr) {
520	      printf("ERROR: null input tensor %zu\n", i);
521	      return false;
522	    }
523	    if (offset + input->bytes > input_size) {
524	      printf("ERROR: input overflow at %zu (%zu + %d > %zu)\n", i, offset,
525	             (int)input->bytes, input_size);
526	      return false;
527	    }
528	    memcpy(input->data.raw, input_data + offset, input->bytes);
529	    offset += input->bytes;
530	  }
531	  return true;
532	}
533	
534	/* Generic output validation for mlzoo_test: walks 1..N output tensors,
535	 * comparing each against the corresponding slice of the reference buffer
536	 * (laid out by concatenating outputs in index order).  Dispatches per
537	 * tensor dtype:
538	 *   int8    -> integer |got - ref|, tol = 2 (same as hr_accnet_test)
539	 *   float32 -> fabsf diff, tol = 1e-2 (same as hr_pnet/attengru_test)
540	 */
541	bool ValidateGenericOutput(tflite::MicroInterpreter& interpreter,
542	                           const uint8_t* reference_data,
543	                           size_t reference_size) {
544	  size_t out_offset = 0;
545	  int max_int8_diff = 0;
546	  float max_float_diff = 0.0f;
547	  bool is_int8 = false;
548	  bool is_float = false;
549	  int total_n = 0;
550	  for (size_t i = 0; i < interpreter.outputs_size(); ++i) {
551	    TfLiteTensor* output = interpreter.output_tensor(i);
552	    if (output == nullptr) {
553	      printf("ERROR: null output tensor %zu\n", i);
554	      return false;
555	    }
556	    if (out_offset + output->bytes > reference_size) {
557	      printf("ERROR: ref overflow at output %zu (%zu + %d > %zu)\n", i,
558	             out_offset, (int)output->bytes, reference_size);
559	      return false;
560	    }
561	    if (output->type == kTfLiteInt8) {
562	      is_int8 = true;
563	      const int8_t* got = reinterpret_cast<const int8_t*>(output->data.raw);
564	      const int8_t* ref =
565	          reinterpret_cast<const int8_t*>(reference_data + out_offset);
566	      const int n = (int)output->bytes;
567	      for (int j = 0; j < n; ++j) {
568	        int d = static_cast<int>(got[j]) - static_cast<int>(ref[j]);
569	        if (d < 0) d = -d;
570	        if (d > max_int8_diff) max_int8_diff = d;
571	      }
572	      total_n += n;
573	    } else if (output->type == kTfLiteFloat32) {
574	      is_float = true;
575	      const float* got = reinterpret_cast<const float*>(output->data.raw);
576	      const float* ref =
577	          reinterpret_cast<const float*>(reference_data + out_offset);
578	      const int n = (int)(output->bytes / sizeof(float));
579	      for (int j = 0; j < n; ++j) {
580	        float d = std::fabs(got[j] - ref[j]);
581	        if (d > max_float_diff) max_float_diff = d;
582	      }
583	      total_n += n;
584	    } else {
585	      printf("ERROR: unsupported output %zu dtype %d (only int8/float32)\n", i,
586	             output->type);
587	      return false;
588	    }
589	    out_offset += output->bytes;
590	  }
591	  if (is_int8) {
592	    printf("[gen] total_elems=%d max_int8_diff=%d\n", total_n,
593	           max_int8_diff);
594	    constexpr int kTol = 2;
595	    if (max_int8_diff > kTol) {
596	      printf("FAIL: max_int8_diff %d > %d\n", max_int8_diff, kTol);
597	      return false;
598	    }
599	    printf("PASS: generic (int8, %zu outputs)\n",
600	           (size_t)interpreter.outputs_size());
601	    return true;
602	  }
603	  if (is_float) {
604	    printf("[gen] total_elems=%d max_abs_diff=%.6f\n", total_n,
605	           (double)max_float_diff);
606	    constexpr float kTol = 1e-2f;
607	    if (max_float_diff > kTol) {
608	      printf("FAIL: max_abs_diff %.6f > %.6f\n", (double)max_float_diff,
609	             (double)kTol);
610	      return false;
611	    }
612	    printf("PASS: generic (float32, %zu outputs)\n",
613	           (size_t)interpreter.outputs_size());
614	    return true;
615	  }
616	  printf("ERROR: no comparable output\n");
617	  return false;
618	}
