620	int Benchmark(const uint8_t* model_data, tflite::PrettyPrintType print_type,
621	              const uint8_t* input_data, size_t input_size,
622	              const uint8_t* reference_data, size_t reference_size,
623	              const char* pnet_variant, bool generic_mode) {
624	  static Profiler profiler;
625	  static Profiler profiler2;
626	  profiler.ClearEvents();
627	  profiler2.ClearEvents();
628	  TfLiteStatus status;
629	  const bool has_ref =
630	      input_data != nullptr && reference_data != nullptr;
631	  /* pnet_mode is the pnet-specific path (fixed shape + pnet_variant set);
632	   * generic_mode is the shape-agnostic accuracy path (mlzoo_test).  Both
633	   * require input+ref; has_ref is the union. */
634	  const bool pnet_mode = has_ref && pnet_variant != nullptr;
635	  struct PnetAbResultReporter {
636	    PnetAbResultReporter(bool enabled_in, const char* variant_in)
637	        : enabled(enabled_in),
638	          variant(variant_in),
639	          total_ticks(0),
640	          passed(false),
641	          emitted(false) {}
642	
643	    ~PnetAbResultReporter() { Emit(); }
644	
645	    void Emit() {
646	      if (enabled && !emitted) {
647	        printf("AB_RESULT variant=%s total_ticks=%lu pass=%d\n", variant,
648	               static_cast<unsigned long>(total_ticks), passed ? 1 : 0);
649	        emitted = true;
650	      }
651	    }
652	
653	    bool enabled;
654	    const char* variant;
655	    uint32_t total_ticks;
656	    bool passed;
657	    bool emitted;
658	  } ab_result(pnet_mode, pnet_variant);
659	  if ((input_data == nullptr) != (reference_data == nullptr)) {
660	    MicroPrintf("benchmark requires both input and reference data");
661	    return -1;
662	  }
663	
664	// use this to keep the application size stable regardless of whether
665	// compression is being used
666	#ifdef USE_TFLM_COMPRESSION
667	  constexpr bool using_compression = true;
668	#else   // USE_TFLM_COMPRESSION
669	  constexpr bool using_compression = false;
670	#endif  // USE_TFLM_COMPRESSION
671	
672	  auto tensor_arena = make_aligned_alloc<16>(kTensorArenaSize);
673	  if (tensor_arena == nullptr) {
674	    MicroPrintf("Failed to allocate tensor arena");
675	    return -1;
676	  }
677	
678	  uint32_t event_handle = profiler.BeginEvent("tflite::GetModel");
679	  const tflite::Model* model = tflite::GetModel(model_data);
680	  profiler.EndEvent(event_handle);
681	
682	  event_handle = profiler.BeginEvent("tflite::CreateOpResolver");
683	  TflmOpResolverNoSignal op_resolver;
684	  status = CreateOpResolverNoSignal(op_resolver);
685	  if (status != kTfLiteOk) {
686	    MicroPrintf("tflite::CreateOpResolver failed");
687	    return -1;
688	  }

